import React, { useState } from 'react';

interface SuccessMessage {
  type: 'success';
  message: string;
}

interface ErrorMessage {
  type: 'error';
  message: string;
  errorCode: number;
}

type MessageProps = SuccessMessage | ErrorMessage;

const MessageDisplay = (props: MessageProps) => {
  const [state, setState] = useState<MessageProps>({ type: 'success', message: 'Operation completed!' });

  if (state.type === 'success') {
    return (
      <div>
        <p style={{ color: 'green' }}>{state.message}</p>
        <button onClick={() => setState({ type: 'success', message: 'Another success!' })}>
          Switch to Success
        </button>
      </div>
    );
  }

  return (
    <div>
      <p style={{ color: 'red' }}>{state.message} (Code: {state.errorCode})</p>
      <button onClick={() => setState({ type: 'success', message: 'Operation completed!' })}>
        Switch to Success
      </button>
    </div>
  );
};

